def _get_scale(
    self, spec: Plot, var: str, prop: Property, values: Series
) -> Scale:

    if var in spec._scales:
        arg = spec._scales[var]
        if arg is None or isinstance(arg, Scale):
            scale = arg
        else:
            scale = prop.infer_scale(arg, values)
    else:
        scale = prop.default_scale(values)

